mapper.insert:
/* imageboard-mapper.xml id="insertImageBoard" 이미지게시판 등록 */
INSERT
  INTO tbts_image_board
     ( mb_id
     , title
     , file_no
     , file_url
     , writer_nm
     , use_yn
     , in_emp_cd
     , in_dtm
     )
VALUES
     ( #{mb_id}
     , #{title}
     , #{file_no}
     , #{file_url}
     , #{writer_nm}
     , 'Y'
     , #{in_emp_cd}
     , NOW()
     )

mapper.update:
/* imageboard-mapper.xml id="updateImageBoard" 이미지게시판 수정 */
UPDATE tbts_image_board
   SET title     = #{title}
     , file_no   = #{file_no}
     , file_url  = #{file_url}
     , writer_nm = #{writer_nm}
     , up_emp_cd = #{up_emp_cd}
     , up_dtm    = NOW()
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}

/* imageboard-mapper.xml id="deleteImageBoard" 이미지게시판 삭제(use_yn='N') */
UPDATE tbts_image_board
   SET use_yn    = 'N'
     , up_emp_cd = #{up_emp_cd}
     , up_dtm    = NOW()
 WHERE mb_id = #{mb_id}
   AND seq   = #{seq}
